(1064, 107, 'mcq', 4, 'إذا علمت أن صيغة أيون الكبريتيت SO₃²⁻، فما اسم الحمض H₂SO₃ المشتق منه؟', null, '["حمض الكبريتوز","حمض الكبريتيك","حمض الهيدروكبريتيك"]'::jsonb, 'تطبيق', 'تطبيق القاعدة على أيون معطى', 'متوسط', 'المذكرة ص40 — تابع ورقة2: كتابة صيغ المركبات التساهمية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
