(1081, 109, 'mcq', 1, 'ما مجموع إلكترونات التكافؤ التي تُستعمل في رسم تركيب لويس لجزيء الأمونيا NH₃؟ (N = 5 ، H = 1)', null, '["5 إلكترونات","8 إلكترونات","11 إلكترونًا"]'::jsonb, 'تطبيق', 'حساب عدد الإلكترونات', 'سهل', 'المذكرة ص41 — ورقة3: التراكيب الجزيئية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
