(1085, 109, 'mcq', 5, 'لماذا يتشابه تركيب لويس لجزيء PH₃ مع تركيب لويس لجزيء NH₃؟', null, '["لأن الفوسفور والنيتروجين في الدورة نفسها","لأن كتلتي الفوسفور والنيتروجين متقاربتان","لأن لكل من الفوسفور والنيتروجين 5 إلكترونات تكافؤ"]'::jsonb, 'فهم', 'تفسير/استنتاج', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص41', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
