(1404, 141, 'mcq', 4, 'تُصنَّف الأملاح المائية من حيث نوع المركب ضمن:', null, '["المركبات التساهمية السائلة","السبائك الفلزية الصلبة","المركبات الأيونية الصلبة"]'::jsonb, 'تذكر', 'تذكر', 'سهل', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1405, 141, 'mcq', 5, 'يبين الجدول صيغ ثلاثة أملاح مائية. أيها تحتوي وحدة الصيغة الواحدة منه على أكبر عدد من جزيئات ماء التبلور؟', '{"headers":["الملح","الصيغة"],"rows":[["كبريتات النحاس II","CuSO₄·5H₂O"],["كربونات الصوديوم","Na₂CO₃·10H₂O"],["كبريتات المغنيسيوم","MgSO₄·7H₂O"]]}'::jsonb, '["كربونات الصوديوم","كبريتات المغنيسيوم","كبريتات النحاس II"]'::jsonb, 'فهم', 'بيانات جدول', 'سهل', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1406, 141, 'mcq', 6, 'ماذا يُسمى الملح الذي يتبقى بعد طرد جزيئات الماء كلها من الملح المائي؟', null, '["الملح المائي","المحلول المشبع","الملح اللامائي"]'::jsonb, 'تذكر', 'تذكر', 'سهل', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1407, 141, 'mcq', 7, 'لديك عينتان: الأولى من CuSO₄·5H₂O والثانية من CuSO₄، ولهما عدد المولات نفسه. أي العبارات الآتية صحيحة؟', null, '["كتلة العينة الأولى أكبر","كتلتا العينتين متساويتان","كتلة العينة الثانية أكبر"]'::jsonb, 'تحليل', 'مقارنة/استنتاج', 'متوسط', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1408, 141, 'essay', 1, 'عرّف كلًا من: الملح المائي، وماء التبلور، ثم وضّح ما تعنيه الصيغة Na₂CO₃·10H₂O.', null, null, 'تذكر', 'تعريف وتفسير', 'سهل', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1409, 141, 'essay', 2, 'قارن بين الملح المائي والملح اللامائي من حيث: (أ) وجود جزيئات الماء في الصيغة. (ب) الكتلة المولية (مثّل بكبريتات النحاس II، Cu = 63.5 ، S = 32.0 ، O = 16.0 ، H = 1.0). (ج) اللون في حالة كبريتات النحاس II.', null, null, 'تحليل', 'مقارنة', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص52', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1410, 141, 'essay', 3, 'احسب النسبة المئوية بالكتلة لماء التبلور في كبريتات النحاس II خماسية الماء CuSO₄·5H₂O، وفسّر لماذا تقل كتلة عينة منها عند تسخينها. (Cu = 63.5 ، S = 32.0 ، O = 16.0 ، H = 1.0)', null, null, 'تطبيق', 'حساب مع تفسير', 'متوسط', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1411, 142, 'mcq', 1, 'ما الخطوة الأولى عند تحليل بيانات تسخين ملح مائي لإيجاد صيغته الكيميائية؟', null, '["حساب كتلة الماء بطرح كتلة الملح اللامائي من كتلة الملح المائي","قسمة كتلة الملح المائي على الكتلة المولية للماء مباشرة","جمع كتلة الملح المائي وكتلة الملح اللامائي معًا"]'::jsonb, 'تذكر', 'تذكر خطوات الحل', 'سهل', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1412, 142, 'mcq', 2, 'سُخّنت عينة كتلتها 5.00 g من كلوريد الباريوم المائي حتى ثبتت كتلتها عند 4.26 g. كم عدد مولات الماء المطرود؟ (H = 1.0 ، O = 16.0)', null, '["0.740 mol","0.278 mol","0.0411 mol"]'::jsonb, 'تطبيق', 'تطبيق (حساب مولات الماء)', 'متوسط', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1413, 142, 'mcq', 3, 'وُجد في عينة من ملح مائي أن عدد مولات الملح اللامائي 0.0200 mol وعدد مولات الماء 0.140 mol. ما عدد جزيئات الماء (x) في صيغة هذا الملح؟', null, '["x = 0.14","x = 7","x = 3.5"]'::jsonb, 'تطبيق', 'تطبيق (النسبة المولية)', 'سهل', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1414, 142, 'mcq', 4, 'سُخّنت عينة كتلتها 1.47 g من كلوريد الكالسيوم المائي فتبقى 1.11 g من CaCl₂ اللامائي. ما صيغة الملح المائي؟ (Ca = 40.0 ، Cl = 35.5 ، H = 1.0 ، O = 16.0)', null, '["CaCl₂·4H₂O","2CaCl₂·H₂O","CaCl₂·2H₂O"]'::jsonb, 'تطبيق', 'حل مشكلة (إيجاد صيغة ملح مائي)', 'متوسط', 'المذكرة ص52–53 — ورقة 4: صيغ الأملاح المائية (تدريب 2)', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1415, 142, 'mcq', 5, 'يبين الجدول نتائج تجربة تسخين عينة من كبريتات المغنيسيوم المائية MgSO₄·xH₂O حتى ثبات الكتلة. ما صيغة الملح المائي؟ (MgSO₄ = 120.3 g/mol ، H₂O = 18.0 g/mol)', '{"headers":["القياس","الكتلة (g)"],"rows":[["البوتقة فارغة","20.00"],["البوتقة + الملح المائي","24.93"],["البوتقة + الملح بعد التسخين حتى ثبات الكتلة","22.41"]]}'::jsonb, '["MgSO₄·H₂O","MgSO₄·7H₂O","MgSO₄·3H₂O"]'::jsonb, 'تحليل', 'تفسير بيانات جدول', 'صعب', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1416, 142, 'mcq', 6, 'ملح مائي من كبريتات الحديد II صيغته FeSO₄·xH₂O، ونسبة الماء فيه بالكتلة 45.3%. ما قيمة x؟ (FeSO₄ = 152.0 g/mol ، H₂O = 18.0 g/mol)', null, '["x = 7","x = 2.5","x = 6"]'::jsonb, 'تطبيق', 'حل مشكلة (نسبة مئوية)', 'صعب', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1417, 142, 'mcq', 7, 'سخّن طالب عينة من ملح مائي ولم يستمر في التسخين حتى ثبات الكتلة، فبقي فيها جزء من الماء. كيف تتأثر قيمة x التي سيحسبها مقارنة بالقيمة الحقيقية؟', null, '["تكون أكبر من الحقيقية","تكون مساوية للحقيقية","تكون أصغر من الحقيقية"]'::jsonb, 'تحليل', 'استنتاج (تحليل مصادر الخطأ)', 'صعب', 'المذكرة ص52 — ورقة 4: صيغ الأملاح المائية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1418, 142, 'essay', 1, 'سُخّنت عينة كتلتها 4.76 g من ملح كلوريد الكوبلت II المائي CoCl₂·xH₂O حتى ثبتت كتلتها عند 2.60 g. أوجد صيغة الملح المائي واكتب اسمه، موضحًا خطوات الحل. (CoCl₂ = 129.9 g/mol ، H₂O = 18.0 g/mol)', null, null, 'تطبيق', 'مسألة بخطوات', 'متوسط', 'المذكرة ص52–53 — ورقة 4: صيغ الأملاح المائية (تدريب 2)', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1419, 142, 'essay', 2, 'سجّل طالب البيانات الآتية عند تسخين كربونات الصوديوم المائية Na₂CO₃·xH₂O في بوتقة: كتلة البوتقة فارغة 25.00 g، والبوتقة مع الملح المائي 30.72 g، وبعد التسخين الأول 27.50 g، وبعد التسخين الثاني 27.12 g، وبعد التسخين الثالث 27.12 g.
