(1729, 173, 'essay', 2, 'سجّل ثلاثة طلاب ضغط غاز في دورق بوحدات مختلفة: الطالب الأول 1520 mmHg، والثاني 202.6 kPa، والثالث 1.5 atm. (أ) حوّل القراءتين الأولى والثانية إلى atm. (ب) أي الطلاب قراءته مختلفة عن الآخرين؟', null, null, 'تطبيق', 'تحويل ومقارنة', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص62', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1730, 173, 'essay', 3, 'قرأ طالب في نشرة الطقس أن الضغط الجوي 650 mmHg في مدينة جبلية، وكتب: «الضغط = 650 × 101.3 = 65845 kPa». (أ) قوّم حل الطالب. (ب) احسب القيمة الصحيحة بوحدة kPa. (ج) هل الناتج الصحيح منطقي؟ علل.', null, null, 'تقويم', 'تقويم حل وتصحيحه', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص62', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1731, 174, 'mcq', 1, 'ينص قانون دالتون للضغوط الجزئية على أن الضغط الكلي لخليط من الغازات:', null, '["يساوي مجموع الضغوط الجزئية للغازات المكونة له","يساوي حاصل ضرب الضغوط الجزئية للغازات المكونة له","يساوي الضغط الجزئي لأثقل غاز في الخليط"]'::jsonb, 'تذكر', 'تذكر نص القانون', 'سهل', 'المذكرة ص63 — ورقة 3: قانون دالتون للضغوط الجزئية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1732, 174, 'mcq', 2, 'أي العلاقات الآتية تعبر عن قانون دالتون؟', null, '["Ptotal = P1 × P2 × P3 × …","Ptotal = P1 − P2 − P3 − …","Ptotal = P1 + P2 + P3 + …"]'::jsonb, 'تذكر', 'تعرف الصيغة', 'سهل', 'المذكرة ص63 — ورقة 3: قانون دالتون للضغوط الجزئية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1733, 174, 'mcq', 3, 'الضغط الجزئي لغاز في خليط هو:', null, '["الضغط الكلي للخليط مقسومًا على عدد الغازات","الضغط الذي يبذله الغاز لو كان وحده في الإناء","الضغط الذي يبذله الغاز الأثقل في الخليط"]'::jsonb, 'تذكر', 'تذكر مفهوم', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1734, 174, 'mcq', 4, 'خليط من O₂ ضغطه الجزئي 3 atm، وN₂ ضغطه الجزئي 4 atm، وCO₂ ضغطه الجزئي 2 atm. كم يساوي الضغط الكلي للخليط؟', null, '["9 atm","24 atm","3 atm"]'::jsonb, 'تطبيق', 'تطبيق مباشر', 'سهل', 'المذكرة ص63 — ورقة 3: قانون دالتون للضغوط الجزئية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1735, 174, 'mcq', 5, 'لا يعتمد الضغط الجزئي للغاز في الخليط على:', null, '["عدد مولات الغاز","نوع الغاز","درجة الحرارة"]'::jsonb, 'فهم', 'فهم العوامل المؤثرة', 'متوسط', 'المذكرة ص63 — ورقة 3: قانون دالتون للضغوط الجزئية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1736, 174, 'mcq', 6, 'يبين الجدول عدد مولات ثلاثة غازات في خليط داخل إناء واحد عند درجة حرارة ثابتة. أي العبارات صحيحة عن ضغوطها الجزئية؟', '{"headers":["الغاز","عدد المولات (mol)"],"rows":[["He","0.20"],["CO₂","0.20"],["N₂","0.10"]]}'::jsonb, '["ضغط CO₂ الجزئي أكبرها لأنه أثقلها","ضغط He الجزئي أصغرها لأنه أخفها","ضغط He الجزئي يساوي ضغط CO₂ الجزئي"]'::jsonb, 'تحليل', 'بيانات جدول/استنتاج', 'صعب', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1737, 174, 'mcq', 7, 'عند إضافة كمية من غاز النيتروجين إلى إناء مغلق فيه غاز الهيليوم مع ثبات الحجم ودرجة الحرارة، فإن الضغط الكلي في الإناء:', null, '["يزداد لأنه يساوي مجموع الضغطين الجزئيين","يقل لأن النيتروجين يقلل ضغط الهيليوم","لا يتغير لأن حجم الإناء ثابت"]'::jsonb, 'تطبيق', 'توقع وتفسير', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1738, 174, 'essay', 1, '(أ) اذكر نص قانون دالتون للضغوط الجزئية واكتب صيغته الرياضية. (ب) عرّف الضغط الجزئي. (ج) اذكر العوامل التي يعتمد عليها الضغط الجزئي للغاز، وعاملًا لا يعتمد عليه.', null, null, 'تذكر', 'ذكر نص وتعريف', 'سهل', 'المذكرة ص63 — ورقة 3: قانون دالتون للضغوط الجزئية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1739, 174, 'essay', 2, 'إناء مغلق يحتوي على خليط من الغازات: H₂ ضغطه الجزئي 2.4 atm، وHe ضغطه الجزئي 1.1 atm، وNe ضغطه الجزئي 0.5 atm. (أ) احسب الضغط الكلي باستخدام قانون دالتون. (ب) إذا سُحب غاز Ne كله من الإناء مع ثبات الحجم ودرجة الحرارة، فكم يصبح الضغط الكلي؟ وهل يتغير الضغط الجزئي لـ H₂؟', null, null, 'تطبيق', 'تطبيق وتفسير', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1740, 174, 'essay', 3, 'قال طالب: «في خليط يحتوي على مول واحد من CO₂ ومول واحد من He في الإناء نفسه، يكون الضغط الجزئي لـ CO₂ أكبر لأن جزيئاته أثقل». قوّم هذه العبارة في ضوء ما تعرفه عن الضغط الجزئي ونظرية الحركة الجزيئية.', null, null, 'تقويم', 'تقويم مفهوم خاطئ', 'صعب', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1741, 175, 'mcq', 1, 'خليط من الغازات النبيلة يحتوي على He ضغطه الجزئي 1.20 atm، وNe ضغطه الجزئي 0.85 atm، وAr ضغطه الجزئي 0.45 atm. ما الضغط الكلي للخليط؟', null, '["0.833 atm","2.50 atm","0.459 atm"]'::jsonb, 'تطبيق', 'حساب الضغط الكلي', 'سهل', 'المذكرة ص63 — ورقة 3: قانون دالتون للضغوط الجزئية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1742, 175, 'mcq', 2, 'الضغط الكلي لخليط من N₂ وCO₂ وO₂ يساوي 1.50 atm. إذا كان الضغط الجزئي لـ N₂ = 0.80 atm ولـ CO₂ = 0.25 atm، فكم الضغط الجزئي لـ O₂؟', null, '["0.45 atm","2.55 atm","0.70 atm"]'::jsonb, 'تطبيق', 'حساب ضغط جزئي مجهول', 'متوسط', 'المذكرة ص63 — ورقة 3: قانون دالتون للضغوط الجزئية', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1743, 175, 'mcq', 3, 'خليط يحتوي على O₂ ضغطه الجزئي 0.30 atm، وN₂ ضغطه الجزئي 380 mmHg، وAr ضغطه الجزئي 0.10 atm. ما الضغط الكلي بوحدة atm؟', null, '["380.4 atm","0.78 atm","0.90 atm"]'::jsonb, 'تطبيق', 'حساب مع توحيد الوحدات', 'صعب', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1744, 175, 'mcq', 4, 'جُمع غاز الهيدروجين فوق الماء عند 25 °C، فكان الضغط الكلي داخل الدورق 99.5 kPa، والضغط الجزئي لبخار الماء عند هذه الدرجة 3.2 kPa. ما الضغط الجزئي للهيدروجين؟', null, '["102.7 kPa","31.1 kPa","96.3 kPa"]'::jsonb, 'تطبيق', 'تطبيق في سياق تجريبي', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1745, 175, 'mcq', 5, 'يبين الجدول الضغوط الجزئية لمكونات الهواء الجاف عند مستوى سطح البحر تقريبًا. ما الضغط الجزئي لبقية الغازات (Ar وCO₂ وغيرهما) معًا؟', '{"headers":["الغاز","الضغط الجزئي (kPa)"],"rows":[["N₂","79.1"],["O₂","21.2"],["بقية الغازات","؟"],["الضغط الكلي","101.3"]]}'::jsonb, '["1.0 kPa","201.6 kPa","57.9 kPa"]'::jsonb, 'تحليل', 'بيانات جدول', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1746, 175, 'mcq', 6, 'وُصل دورقان متساويا الحجم عند درجة الحرارة نفسها، يحتوي الأول على O₂ بضغط 0.45 atm، والثاني على N₂ بضغط 0.32 atm، ثم نُقل الغازان كلاهما إلى دورق ثالث مماثل يحتوي على He بضغط 0.18 atm. ما الضغط الكلي في الدورق الثالث؟', null, '["0.77 atm","0.95 atm","0.32 atm"]'::jsonb, 'تحليل', 'حل مشكلة', 'صعب', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1747, 175, 'mcq', 7, 'أسطوانة غوص تحتوي على خليط من O₂ وHe ضغطه الكلي 5.00 atm. إذا كان الضغط الجزئي لـ O₂ يساوي 1.05 atm، فكم الضغط الجزئي لـ He بوحدة kPa؟', null, '["3.95 kPa","613 kPa","400 kPa"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'صعب', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1748, 175, 'essay', 1, 'جُمع غاز الأكسجين فوق الماء عند 22 °C، فكان الضغط الكلي في الدورق 100.2 kPa، والضغط الجزئي لبخار الماء عند هذه الدرجة 2.6 kPa. (أ) لماذا لا يساوي ضغط الأكسجين الضغط الكلي في الدورق؟ (ب) احسب الضغط الجزئي للأكسجين بوحدة kPa. (ج) حوّله إلى atm.', null, null, 'تطبيق', 'مسألة في سياق تجريبي', 'متوسط', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
(1749, 175, 'essay', 2, 'قيست الضغوط الجزئية لثلاثة غازات في خليط بوحدات مختلفة: CO₂ = 0.40 atm، وN₂ = 456 mmHg، وO₂ = 20.3 kPa. (أ) حوّل الضغوط كلها إلى atm. (ب) احسب الضغط الكلي بوحدة atm. (ج) أي الغازات أكبر ضغطًا جزئيًا؟', null, null, 'تطبيق', 'توحيد وحدات وحساب', 'صعب', 'محتوى مكمّل (غير موجود في نص المذكرة) — المذكرة ص63', 'approved', false, 'ai_generated', '2026-10-10'::timestamptz),
